from pathlib import Path
import json

root = Path(__file__).resolve().parents[1]
s = json.loads((root / 'results/summary.json').read_text())
metrics = s['metrics']
win = next(r for r in metrics if r['model'] == s['winner'])
base = metrics[0]
improvement = 100 * (1 - win['test_log_mae'] / base['test_log_mae'])

def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>' + ''.join('<th scope="col">' + x + '</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + str(x) + '</td>' for x in row) + '</tr>' for row in rows) + '</tbody></table></div>'

def section(n, id, title, body):
    return f'<section id="{id}"><div class="eyebrow">{n} / {id}</div><h2>{title}</h2>{body}</section>'

def figure(file, alt, caption):
    return f'<figure><img src="assets/{file}.svg" alt="{alt}" loading="lazy"><figcaption>{caption}</figcaption></figure>'

html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A reproducible study of online news popularity: modest predictive signal, a chronological evaluation, and an interactive error explorer."><title>Understanding & Predicting Online News Popularity</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,400;0,600;0,700;1,400&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/style.css"><script defer src="assets/results.js"></script><script defer src="assets/app.js"></script></head><body><header><nav aria-label="Main"><a class="brand" href="#">News / Popularity</a><div class="section-links" aria-label="Project sections"><a href="#question">Question</a><a href="#data">Data</a><a href="#preprocessing">Preprocessing</a><a href="#methods">Methods</a><a href="#evaluation">Evaluation</a><a href="#results">Results</a><a href="#errors">Errors</a><a href="#limitations">Limitations</a><a href="#explorer">Explore</a><a href="#conclusion">Conclusion</a><a href="#tools">Tools &amp; AI</a><a href="#reproduce">Reproduce</a></div></nav></header><main><div class="hero" id="home"><div class="eyebrow">ES 335 · Course project · 2026</div><h1>Can we tell which news will travel?</h1><p class="lead">Understanding and predicting online news popularity, using article features and an honest test on later publications.</p><p class="byline">Goutham (25110359) &amp; Adimulam Mokshajna Sai Satya Sri Harsha (25110011)<br>UCI Online News Popularity · Mashable · 2013–2014</p>'''

html += f'<blockquote>Content carries a little signal. Predicting a viral hit remains much harder.</blockquote><p>The validation-selected random forest reduces test log error by {improvement:.1f}% against a median baseline. That is a measurable but limited improvement, not a reliable forecast of virality.</p></div>'

html += section('01', 'question', 'A prediction question with a clear boundary.', '''<p><strong>Can article-level features improve predictions of recorded social shares over a constant baseline for later Mashable articles?</strong> One row is one article. The target is <code>shares</code>, the social-share count recorded by the dataset authors.</p><p>We imagine making a prediction at publication, after the article content and channel are known. Inputs are content statistics, media/link counts, sentiment, channel flags and publication weekday. We deliberately exclude historical-share summaries and original topic-model features with uncertain fitting provenance.</p><p>This is a retrospective benchmark. All labels come from a snapshot acquired on 8 January 2015: older articles have had more time to accumulate shares. The data cannot answer “how many shares after seven days?” or prove that changing a headline causes more sharing.</p>''')

html += section('02', 'data', 'The data, before the model.', f'''<p>The <a href="https://archive.ics.uci.edu/dataset/332/online+news+popularity">UCI Online News Popularity dataset</a> provides numerical summaries of Mashable articles, not their full text. The supplied CSV contains <strong>{s['rows']:,} articles and 61 columns</strong>: 58 candidate predictors, URL, article age and the target. The current UCI page lists 39,797 instances; we report the actual supplied file count, without silently adding or deleting rows.</p>''' + table(['Variable group', 'Examples', 'Role'], [['Content & structure', 'Title/content length, unique-word rates, images, videos, links', 'Publication-time signals'], ['Context', 'Channel and weekday indicator variables', 'Publication context'], ['Text summaries', 'Subjectivity and positive/negative polarity', 'Imperfect numerical text proxies'], ['Outcome', 'Recorded social shares', 'Regression target']]) + f'''<p><strong>Quality checks.</strong> URLs are unique; there are no original missing cells or negative targets. {s['zero_content']:,} rows have zero content tokens: these may represent extraction failures or non-text articles, so we retain them without claiming they are genuinely empty. Each of three ratio fields contains one value outside [0,1]; these cells become missing values, then receive training-fitted median imputation.</p><p>The median is 1,400 shares, the 90th percentile is 6,200, the 99th percentile is about 31,657 and the maximum is 843,300. This extreme right tail motivates the log target.</p>''' + figure('distribution', 'Histogram of log-transformed share counts', 'Descriptive distribution over the full file. It describes the dataset; it is not used to choose the split or tune models.') + '''<p class="small">Dataset: Fernandes, Vinagre, Cortez & Sernadela (2015), <a href="https://doi.org/10.24432/C5NS3V">doi:10.24432/C5NS3V</a>, CC BY 4.0. Feature statistics are used under that license; article text remains owned by Mashable.</p>''')

html += section('03', 'preprocessing', 'Conservative inputs. Training-only transformations.', '''<p>Column names have surrounding whitespace stripped. Dates are parsed from article URLs solely for splitting; neither URLs, dates nor <code>timedelta</code> enter the models. No rows or viral targets are removed, no outcomes are winsorized, and there is no target-driven feature selection.</p><p>We exclude nine <code>kw_*</code> fields and three <code>self_reference_*</code> fields: their share-based histories cannot be independently verified as known at publication. We also exclude five <code>LDA_*</code> fields because their original corpus-fitting procedure cannot be reconstructed from these statistics. This is a conservative provenance choice, not evidence that LDA itself is leaky.</p><p><strong>41 inputs remain.</strong> Impossible values in the three documented word-rate fields and any nonfinite predictors become missing. The imputer learns medians only from the fitting partition. Ridge additionally uses means and standard deviations learned by <code>StandardScaler</code> on that partition. Trees do not need scaling. Existing 0/1 indicators are retained.</p><p>Models fit <code>z = ln(1 + shares)</code>. We invert with <code>exp(ẑ) − 1</code> and clip negative predictions to zero. This emphasizes relative errors and compresses the viral tail. Inverting a mean log prediction does not estimate the raw conditional mean; raw-share forecasts can therefore be systematically low.</p>''')

html += section('04', 'methods', 'Start simple, then compare three families.', table(['Method', 'Core idea & reason', 'Fixed choices and validation grid'], [['Median baseline', 'Constant median log-share prediction; minimizes absolute log error with no content signal', 'No tuning; refitted on train + validation for final test'], ['Ridge regression', 'Linear squared log-error objective with L2 penalty; tests additive signal and assumes an approximately linear relationship', 'α ∈ {1, 100}; standardized inputs'], ['Random forest', 'Average of randomized regression trees; captures nonlinearities and interactions with no linearity assumption', '150 trees; max_features=0.8; leaf size ∈ {10, 30}; seed 335'], ['Boosted trees', 'Sequential trees fit squared log-error residuals; captures nonlinear structure but can overfit', '150 rounds; learning rate 0.05; L2=10; leaves ∈ {15, 31}; early stopping off; seed 335']]) + '''<p>The learned models optimize squared error on log shares; the evaluation prioritizes absolute log error for robustness. These objectives differ, so the median baseline remains a meaningful comparator. Complexity is justified only by evidence on validation data. The full seven-run grid is preserved in the repository.</p>''')

html += section('05', 'evaluation', 'Let earlier articles predict later articles.', '''<p>Sort the unique publication dates; the first 60% of dates form training, the next 20% validation and the last 20% test. Every article from one date stays together. Percentages describe date groups, so row proportions differ. This simulates forward use better than a shuffled split, although it does not solve unequal label-exposure times.</p><div class="split" aria-hidden="true"><span>Earlier / training (60% dates)</span><span>Validation (20%)</span><span>Later / test (20%)</span></div>''' + table(['Partition', 'Publication dates', 'Articles'], [[k.capitalize(), v['start'] + ' → ' + v['end'], f"{v['n']:,}"] for k, v in s['splits'].items()]) + '''<p>Each candidate fits on training only. Validation log MAE chooses the settings within each family and the overall model. After freezing those choices, each family is refitted on training + validation, including fresh preprocessing, then evaluated on the same untouched test dates. No test score chooses hyperparameters or the winning family.</p><p><strong>Primary metric: log MAE</strong> = mean |ln(1+y) − ln(1+ŷ)|. Lower is better; for large counts, an error of ln(2) ≈ 0.693 corresponds to a factor-of-two miss. <strong>RMSLE</strong> squares log errors before averaging and penalizes large relative misses more. <strong>MAE in shares</strong> reports typical absolute magnitude on the original scale and is sensitive to viral articles. Log-space R² is also included in the results file.</p>''')

html += section('06', 'results', 'A modest improvement, measured honestly.', table(['Model', 'Validation log MAE', 'Test log MAE ↓', 'Test RMSLE ↓', 'Test MAE (shares) ↓'], [[r['model'], f"{r['validation_log_mae']:.4f}", f"{r['test_log_mae']:.4f}", f"{r['test_rmsle']:.4f}", f"{r['test_mae_shares']:,.0f}"] for r in metrics]) + f'''<p>The random forest wins on validation (0.6038), before test evaluation. On test, its log MAE is {win['test_log_mae']:.4f} versus {base['test_log_mae']:.4f} for the baseline: a <strong>{improvement:.1f}% relative reduction</strong>. Raw MAE improves by only {100*(1-win['test_mae_shares']/base['test_mae_shares']):.1f}%. The close learned-model scores give little support for claiming a decisive advantage of one nonlinear method.</p><p>A paired bootstrap resamples whole test publication days 2,000 times (seed 335). The 95% percentile interval for baseline-minus-forest log MAE is {s['paired_day_bootstrap_95_log_mae_improvement'][0]:.4f} to {s['paired_day_bootstrap_95_log_mae_improvement'][1]:.4f}. Positive values favor the forest. This conditional interval reflects variation across sampled days; it does not include training variability, serial dependence between days or future distribution shifts.</p>''' + figure('comparison', 'Bar chart comparing test log MAE of four models', 'All test scores use final train + validation fits. Lower is better. The selected family is highlighted.'))

html += section('07', 'errors', 'The hard part is the tail.', figure('errors', 'Hexbin plot of observed versus predicted log shares', 'Random forest test predictions. The dashed diagonal is a perfect forecast; points below it are underpredictions.') + table(['Observed shares', 'Test n', 'Log MAE', 'Median actual', 'Median predicted'], [[g['group'], g['n'], f"{g['log_mae']:.3f}", f"{g['median_actual']:,.0f}", f"{g['median_prediction']:,.0f}"] for g in s['error_groups']]) + '''<p>For the 444 test articles with at least 10,000 shares, the median observed count is 17,150 but the median prediction is about 2,032. For low-share articles the direction reverses: predicted counts tend to be too high. Predictions concentrate around common outcomes, consistent with weak features and an unpredictable tail.</p><p>These outcome-defined bands diagnose errors after evaluation; they are not information available at prediction time. The decision explorer below shows which articles the model would promote and which popular articles it misses. Its case-table row IDs are zero-based CSV data-row indices, so the repository can trace each case without republishing article text or inventing explanations from unseen headlines.</p>''')

html += section('08', 'limitations', 'What this evidence does—and does not—support.', '''<p>The data cover one publisher and an old social-media environment. Results do not automatically transfer to modern platforms or other publishers. Share counts are cumulative snapshots with unequal exposure durations; publication date is a split key, not a guarantee of clean prospective labels. Earlier article labels may include shares accumulated after later articles were published, so this experiment is not a true as-of-time deployment simulation.</p><p>Original text, audience size, recommendation placement, social-network structure and promotional activity are unavailable. Provided text statistics cannot be fully audited or rebuilt. Removing uncertain feature groups reduces provenance risk but does not certify every remaining extraction step. The single temporal holdout and small validation grid also limit conclusions about stability and optimality.</p><p>No causal effects, accuracy percentage, prediction intervals for individual articles or guaranteed viral-article detection are claimed. Better next steps would be fixed-horizon labels, timestamped feature histories, repeated rolling-origin validation and a separate future dataset.</p><blockquote>We find weak but useful predictive signal relative to a simple baseline. We do not find a dependable way to forecast viral success.</blockquote>''')

html += section('09', 'explorer', 'Would the model choose the right articles?', '''<p>Imagine an editor can promote only <strong>10% of articles</strong>. Does ranking by predicted shares find more popular articles than choosing randomly? Change the budget and what “popular” means to see the trade-off.</p><div class="controls"><label>Rank articles using<select id="model"></select></label><label>Channel<select id="channel"><option value="all">All channels</option></select></label><label>Promotion budget: <span id="budget-label">10%</span><input id="budget" type="range" min="1" max="50" step="1" value="10"></label><label>Popular means at least<select id="threshold"><option value="1400">1,400 shares</option><option value="5000" selected>5,000 shares</option><option value="10000">10,000 shares</option></select></label></div><div id="readout" class="readout" role="status" aria-live="polite"></div><p id="interpretation"></p><canvas role="img" aria-label="Popularity gains curve"></canvas><p class="small">Horizontal axis: share of articles promoted, ranked by model prediction. Vertical axis: share of all popular articles captured. Green: model ranking. Dashed gray: expected random selection. Orange: best possible ranking with hindsight. The marker is your chosen budget.</p><h3>Inspect the shortlist and what it missed</h3><label class="case-control">Show<select id="case-view"><option value="selected">Top 8 promoted articles</option><option value="missed">Top 8 missed popular articles</option></select></label><div class="table-wrap"><table><thead><tr><th scope="col">Row ID</th><th scope="col">Date</th><th scope="col">Channel</th><th scope="col">Predicted shares</th><th scope="col">Observed shares</th><th scope="col">Outcome</th></tr></thead><tbody id="cases"></tbody></table></div><p class="small"><strong>How to read this.</strong> Precision is the fraction of promoted articles that were popular; recall is the fraction of all popular articles captured. Lift compares precision with the popularity rate of the whole selected channel. Popularity labels score the ranking after selection; they never decide which articles the model promotes.</p><details><summary>Assumptions and limits of this interaction</summary><p>This is a retrospective allocation exercise across the held-out period, assuming all candidate feature vectors are available together and each promotion costs the same. It is not a live daily scheduling policy, a new trained classifier or evidence that promotion causes extra shares. The popularity threshold changes evaluation labels, not predictions. Random selection has an expected precision equal to the popularity rate; the orange ceiling requires impossible advance knowledge of outcomes.</p><p>The constant baseline has no ranking signal, so its curve and metrics show the analytical expectation for random tie-breaking. Other tied predictions break by original row ID. Exploring these test results does not change the validation-selected model. Outcome-defined channels or thresholds should not be used to retune it.</p></details><noscript><p>Enable JavaScript to use the decision explorer. Main project results remain available above.</p></noscript>''')

html += section('10', 'conclusion', 'Small gains, clear limits.', f'''<p>We asked whether article-level features improve predictions of recorded social shares over a constant baseline for later Mashable articles. The validation-selected {s['winner'].lower()} lowers test log MAE from {base['test_log_mae']:.4f} to {win['test_log_mae']:.4f}, a {improvement:.1f}% relative reduction, while raw-share MAE improves by only {100*(1-win['test_mae_shares']/base['test_mae_shares']):.1f}%. The paired-day bootstrap 95% interval for the absolute log-MAE improvement is {s['paired_day_bootstrap_95_log_mae_improvement'][0]:.4f}–{s['paired_day_bootstrap_95_log_mae_improvement'][1]:.4f}, conditional on the fitted models and sampled test days. This supports weak predictive signal in this benchmark, while viral articles remain difficult to predict. Cumulative snapshot labels, a single publisher and unknown exposure histories limit generalization; these predictions establish no causal effects.</p>''')

html += section('11', 'tools', 'Tools &amp; AI use', '''<p>Python, pandas, NumPy and scikit-learn supported the analysis and model evaluation, with Matplotlib used for charts. OpenAI Codex assisted with analysis code, debugging, documentation and website presentation; Claude provided review suggestions. Reported scores come from the computed outputs; the authors remain responsible for understanding the methods and checking the results.</p>''')

html += section('12', 'reproduce', 'Code, data and the exact recipe.', f'''<p><a id="repository-2" href="https://github.com/GOUTHAM018-MAKER/Online-news-Popularity-ML">Source repository and README ↗</a> contains the setup, full outputs, citations and documentation. The essential steps are collected below.</p><details><summary>Show data access, run commands and result files</summary><p>Download the <a href="https://archive.ics.uci.edu/dataset/332/online+news+popularity">UCI Online News Popularity archive</a> (CC BY 4.0) and save it as <code>data/online+news+popularity.zip</code>. Run from the repository root:</p><pre><code>python -m venv .venv
source .venv/bin/activate
pip install -r requirements.txt
python src/analyze.py --data &quot;data/online+news+popularity.zip&quot;
python src/build_site.py</code></pre><p class="small">Windows PowerShell activation: <code>.venv\\Scripts\\Activate.ps1</code>. To preview: <code>python -m http.server 8000 --directory docs</code>, then open localhost:8000.</p><p>Split the sorted unique publication dates 60/20/20, keeping all articles from a date together. Fit preprocessing on the fitting partition only; choose settings and the model on validation, then refit on training + validation before final testing. Random seed: <strong>335</strong>.</p>''' + table(['Partition', 'Publication dates', 'Articles'], [[k.capitalize(), v['start'] + ' → ' + v['end'], f"{v['n']:,}"] for k, v in s['splits'].items()]) + f'''<p class="checksum">CSV SHA-256: <code>{s['csv_sha256']}</code></p>''' + table(['Result file', 'What it records'], [['results/summary.json', 'Complete run summary, environment and checksum'], ['results/metrics.csv', 'Final metrics and selected settings for every model'], ['results/validation_trials.json', 'Every candidate setting and validation log MAE'], ['results/splits.csv', 'Original row ID, publication date and exact split'], ['results/test_predictions.csv', 'Held-out outcomes and predictions for all models'], ['results/largest_errors.csv', 'Largest selected-model absolute log errors'], ['results/feature_manifest.json', 'Included and excluded columns']]) + '''<p class="small">The executable analysis and a notebook are in <code>src/</code> and <code>notebooks/</code>. No additional unreported model experiments are claimed.</p></details>''')

html += '</main><footer>Understanding & Predicting Online News Popularity · ES 335<br>Evidence over headline scores. Dataset © its creators, CC BY 4.0.<p class="small"><a id="repository" href="https://github.com/GOUTHAM018-MAKER/Online-news-Popularity-ML">Source repository &amp; README ↗</a> · Reproduction steps, data access, full results and citations are documented in the README.</p></footer></body></html>'

(root / 'docs/index.html').write_text(html)
(root / 'docs/README.md').write_text((root / 'README.md').read_text())
print("Website generated successfully!")
